[
  {
    "doctype": "Web Page",
    "name": "activity-detail",
    "title": "Activity Detail",
    "route": "activity-detail",
    "published": 1,
    "dynamic_template": 1,
    "full_width": 1,
    "show_title": 0,
    "show_sidebar": 0,
    "insert_style": 1,
    "content_type": "HTML",
    "css": "
@import url('https://fonts.googleapis.com/css2?family=DM+Sans:ital,opsz,wght@0,9..40,300;0,9..40,400;0,9..40,500;0,9..40,600;1,9..40,300&family=DM+Serif+Display:ital@0;1&display=swap');

*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

.gad {
  font-family: 'DM Sans', sans-serif;
  background: #f5f5f3;
  min-height: 100vh;
  padding-bottom: 4rem;
}

/* ── Topbar ── */
.gad-topbar {
  background: #fff;
  border-bottom: 1px solid rgba(0,0,0,0.08);
  padding: 0 2.5rem;
  height: 56px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  position: sticky;
  top: 0;
  z-index: 100;
}
.gad-logo {
  font-family: 'DM Serif Display', serif;
  font-size: 18px;
  color: #1a1a18;
}
.gad-logo span { color: #1D9E75; }
.gad-back {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-size: 13px;
  font-weight: 500;
  color: #6c6b67;
  text-decoration: none;
  transition: color 0.15s;
}
.gad-back:hover { color: #1D9E75; text-decoration: none; }

/* ── Main ── */
.gad-main {
  max-width: 860px;
  margin: 0 auto;
  padding: 3rem 1.5rem 0;
}

/* ── Hero header ── */
.gad-hero {
  background: #1a1a18;
  border-radius: 20px;
  padding: 2.5rem;
  margin-bottom: 1.5rem;
  position: relative;
  overflow: hidden;
}
.gad-hero-bg {
  position: absolute;
  inset: 0;
  background: linear-gradient(135deg, #1a1a18 60%, #2a3a30);
  z-index: 0;
}
.gad-hero-content { position: relative; z-index: 1; }
.gad-hero-eyebrow {
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: #1D9E75;
  margin-bottom: 8px;
}
.gad-hero-title {
  font-family: 'DM Serif Display', serif;
  font-size: 34px;
  color: #fff;
  letter-spacing: -0.02em;
  line-height: 1.15;
  margin-bottom: 1.2rem;
}
.gad-hero-meta {
  display: flex;
  align-items: center;
  gap: 16px;
  flex-wrap: wrap;
}
.gad-hero-badge {
  display: inline-block;
  font-size: 11px;
  font-weight: 600;
  padding: 4px 12px;
  border-radius: 20px;
  letter-spacing: 0.04em;
  background: rgba(255,255,255,0.1);
  color: rgba(255,255,255,0.85);
  border: 1px solid rgba(255,255,255,0.15);
}
.gad-hero-date {
  font-size: 13px;
  color: rgba(255,255,255,0.5);
}

/* ── Status banner ── */
.gad-status-banner {
  border-radius: 14px;
  padding: 1.2rem 1.5rem;
  margin-bottom: 1.5rem;
  display: flex;
  align-items: center;
  gap: 12px;
}
.gad-status-banner.approved { background: #E1F5EE; border: 1px solid #A8E6CF; }
.gad-status-banner.pending  { background: #FFF8E7; border: 1px solid #FFD98A; }
.gad-status-banner.rejected { background: #FDE8E8; border: 1px solid #FBBBBA; }
.gad-status-banner.draft    { background: #F0F0EE; border: 1px solid #DDDDD8; }
.gad-status-icon { font-size: 22px; flex-shrink: 0; }
.gad-status-text h3 { font-size: 14px; font-weight: 600; color: #1a1a18; margin-bottom: 2px; }
.gad-status-text p  { font-size: 13px; color: #6c6b67; }

/* ── Grid ── */
.gad-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 1.5rem;
  margin-bottom: 1.5rem;
}
@media (max-width: 600px) { .gad-grid { grid-template-columns: 1fr; } }

/* ── Card ── */
.gad-card {
  background: #fff;
  border: 1px solid rgba(0,0,0,0.08);
  border-radius: 16px;
  overflow: hidden;
}
.gad-card.full { grid-column: 1 / -1; }
.gad-card-header {
  padding: 1rem 1.5rem;
  border-bottom: 1px solid rgba(0,0,0,0.07);
  display: flex;
  align-items: center;
  gap: 8px;
}
.gad-card-icon { font-size: 16px; }
.gad-card-title {
  font-size: 12px;
  font-weight: 600;
  letter-spacing: 0.07em;
  text-transform: uppercase;
  color: #888780;
}
.gad-card-body { padding: 1.5rem; }

/* ── Fields ── */
.gad-field { margin-bottom: 1.2rem; }
.gad-field:last-child { margin-bottom: 0; }
.gad-field-label {
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.07em;
  text-transform: uppercase;
  color: #aaa9a4;
  margin-bottom: 4px;
}
.gad-field-value {
  font-size: 15px;
  font-weight: 500;
  color: #1a1a18;
}
.gad-field-value.mono { font-family: monospace; font-size: 13px; color: #6c6b67; }

/* ── Certificate ── */
.gad-cert-link {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  background: #1a1a18;
  color: #fff;
  font-size: 13px;
  font-weight: 500;
  padding: 10px 18px;
  border-radius: 10px;
  text-decoration: none;
  transition: background 0.15s;
}
.gad-cert-link:hover { background: #1D9E75; text-decoration: none; color: #fff; }
.gad-cert-none {
  font-size: 13px;
  color: #aaa9a4;
  font-style: italic;
}

/* ── Photos gallery ── */
.gad-gallery {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(160px, 1fr));
  gap: 12px;
}
.gad-gallery-item { border-radius: 10px; overflow: hidden; aspect-ratio: 4/3; background: #f0f0ee; }
.gad-gallery-item img {
  width: 100%; height: 100%;
  object-fit: cover;
  transition: transform 0.2s;
  cursor: pointer;
}
.gad-gallery-item img:hover { transform: scale(1.04); }
.gad-gallery-cap { font-size: 11px; color: #888780; margin-top: 5px; text-align: center; }
.gad-no-photos { font-size: 13px; color: #aaa9a4; font-style: italic; }

/* ── Timeline ── */
.gad-timeline { padding: 1.5rem; }
.gad-tl-item {
  display: flex;
  gap: 14px;
  margin-bottom: 0;
  position: relative;
}
.gad-tl-item:not(:last-child) .gad-tl-line::after {
  content: '';
  position: absolute;
  left: 11px;
  top: 26px;
  width: 2px;
  height: calc(100% + 8px);
  background: rgba(0,0,0,0.08);
}
.gad-tl-left { display: flex; flex-direction: column; align-items: center; flex-shrink: 0; }
.gad-tl-dot {
  width: 24px; height: 24px;
  border-radius: 50%;
  display: flex; align-items: center; justify-content: center;
  font-size: 12px;
  flex-shrink: 0;
  position: relative;
  z-index: 1;
}
.gad-tl-line { position: relative; width: 2px; flex: 1; background: transparent; min-height: 32px; }
.gad-tl-right { padding-bottom: 2rem; }
.gad-tl-right:last-child { padding-bottom: 0; }
.gad-tl-state {
  font-size: 14px;
  font-weight: 600;
  color: #1a1a18;
  margin-bottom: 2px;
}
.gad-tl-desc { font-size: 12px; color: #888780; }

.gad-tl-dot.done     { background: #E1F5EE; color: #1D9E75; }
.gad-tl-dot.active   { background: #FFF8E7; color: #F5A524; }
.gad-tl-dot.rejected { background: #FDE8E8; color: #E24B4A; }
.gad-tl-dot.future   { background: #f0f0ee; color: #ccc; }

/* ── Actions footer ── */
.gad-footer-actions {
  margin-top: 2rem;
  display: flex;
  gap: 10px;
  flex-wrap: wrap;
}
.gad-action-btn {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  font-size: 13px;
  font-weight: 500;
  padding: 10px 20px;
  border-radius: 10px;
  border: 1px solid rgba(0,0,0,0.15);
  background: #fff;
  color: #1a1a18;
  cursor: pointer;
  text-decoration: none;
  transition: background 0.1s, transform 0.1s;
}
.gad-action-btn:hover { background: #f5f5f3; text-decoration: none; color: #1a1a18; transform: translateY(-1px); }
.gad-action-btn.primary { background: #1a1a18; color: #fff; border-color: #1a1a18; }
.gad-action-btn.primary:hover { background: #1D9E75; border-color: #1D9E75; color: #fff; }

/* ── Lightbox ── */
.gad-lightbox {
  display: none;
  position: fixed; inset: 0;
  background: rgba(0,0,0,0.85);
  z-index: 999;
  align-items: center;
  justify-content: center;
  padding: 2rem;
}
.gad-lightbox.open { display: flex; }
.gad-lightbox img {
  max-width: 100%; max-height: 90vh;
  border-radius: 12px;
  box-shadow: 0 20px 60px rgba(0,0,0,0.5);
}
.gad-lightbox-close {
  position: absolute;
  top: 1.5rem; right: 1.5rem;
  background: rgba(255,255,255,0.1);
  color: #fff;
  border: none;
  border-radius: 50%;
  width: 40px; height: 40px;
  font-size: 20px;
  cursor: pointer;
  display: flex; align-items: center; justify-content: center;
}
.gad-lightbox-close:hover { background: rgba(255,255,255,0.2); }

/* ── Error / not found ── */
.gad-error {
  text-align: center;
  padding: 5rem 2rem;
  color: #888780;
}
.gad-error h2 { font-size: 24px; color: #1a1a18; margin-bottom: 8px; }
.gad-error p  { font-size: 14px; }
