    "main_section_html": "
{% set doc_name = frappe.form_dict.get('name') %}

<div class=\"gad\">
  <nav class=\"gad-topbar\">
    <div class=\"gad-logo\">GAM<span>ARG</span></div>
    <a href=\"/student-dashboard\" class=\"gad-back\">
      <svg width=\"14\" height=\"14\" viewBox=\"0 0 14 14\" fill=\"none\"><path d=\"M9 2L4 7l5 5\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></svg>
      Back to Dashboard
    </a>
  </nav>

  <div class=\"gad-main\">

  {% if not doc_name %}
    <div class=\"gad-error\">
      <h2>No activity specified</h2>
      <p>Please go back to your dashboard and select an activity.</p>
    </div>

  {% else %}
    {% set doc = frappe.get_doc('Activity Management', doc_name) if frappe.db.exists('Activity Management', doc_name) else None %}

    {% if not doc or doc.owner != frappe.session.user %}
    <div class=\"gad-error\">
      <h2>Activity not found</h2>
      <p>This activity doesn't exist or you don't have access to it.</p>
    </div>

    {% else %}
    {% set ws = doc.workflow_state %}

    {# ── Hero ── #}
    <div class=\"gad-hero\">
      <div class=\"gad-hero-bg\"></div>
      <div class=\"gad-hero-content\">
        <p class=\"gad-hero-eyebrow\">Activity Detail</p>
        <h1 class=\"gad-hero-title\">{{ doc.event_name }}</h1>
        <div class=\"gad-hero-meta\">
          <span class=\"gad-hero-badge\">{{ doc.category }}</span>
          <span class=\"gad-hero-date\">{{ doc.event_date.strftime('%d %B %Y') if doc.event_date else 'No date' }}</span>
        </div>
      </div>
    </div>

    {# ── Status banner ── #}
    {% if ws == 'Approved' %}
    <div class=\"gad-status-banner approved\">
      <span class=\"gad-status-icon\">✅</span>
      <div class=\"gad-status-text\">
        <h3>Verified &amp; Approved</h3>
        <p>This activity has been verified. You can download your certificate of participation.</p>
      </div>
    </div>
    {% elif ws == 'Rejected' %}
    <div class=\"gad-status-banner rejected\">
      <span class=\"gad-status-icon\">❌</span>
      <div class=\"gad-status-text\">
        <h3>Activity Rejected</h3>
        <p>Your submission was rejected. You can edit and resubmit it from the dashboard.</p>
      </div>
    </div>
    {% elif ws == 'Pending Approval' %}
    <div class=\"gad-status-banner pending\">
      <span class=\"gad-status-icon\">⏳</span>
      <div class=\"gad-status-text\">
        <h3>Pending Verification</h3>
        <p>Your submission is under review by faculty. You'll be notified once it's processed.</p>
      </div>
    </div>
    {% else %}
    <div class=\"gad-status-banner draft\">
      <span class=\"gad-status-icon\">📝</span>
      <div class=\"gad-status-text\">
        <h3>Draft</h3>
        <p>This activity hasn't been submitted for review yet.</p>
      </div>
    </div>
    {% endif %}

    <div class=\"gad-grid\">

      {# ── Activity Info ── #}
      <div class=\"gad-card\">
        <div class=\"gad-card-header\">
          <span class=\"gad-card-icon\">📋</span>
          <span class=\"gad-card-title\">Activity Info</span>
        </div>
        <div class=\"gad-card-body\">
          <div class=\"gad-field\">
            <div class=\"gad-field-label\">Event Name</div>
            <div class=\"gad-field-value\">{{ doc.event_name }}</div>
          </div>
          <div class=\"gad-field\">
            <div class=\"gad-field-label\">Category</div>
            <div class=\"gad-field-value\">{{ doc.category }}</div>
          </div>
          <div class=\"gad-field\">
            <div class=\"gad-field-label\">Event Date</div>
            <div class=\"gad-field-value\">{{ doc.event_date.strftime('%d %B %Y') if doc.event_date else '—' }}</div>
          </div>
          <div class=\"gad-field\">
            <div class=\"gad-field-label\">Document ID</div>
            <div class=\"gad-field-value mono\">{{ doc.name }}</div>
          </div>
        </div>
      </div>

      {# ── Participant Info ── #}
      <div class=\"gad-card\">
        <div class=\"gad-card-header\">
          <span class=\"gad-card-icon\">👤</span>
          <span class=\"gad-card-title\">Participant</span>
        </div>
        <div class=\"gad-card-body\">
          <div class=\"gad-field\">
            <div class=\"gad-field-label\">Type</div>
            <div class=\"gad-field-value\">{{ doc.participant_type }}</div>
          </div>
          <div class=\"gad-field\">
            <div class=\"gad-field-label\">Participant</div>
            <div class=\"gad-field-value\">{{ doc.participant }}</div>
          </div>
          <div class=\"gad-field\">
            <div class=\"gad-field-label\">Department</div>
            <div class=\"gad-field-value\">{{ doc.department }}</div>
          </div>
        </div>
      </div>

      {# ── Certificate ── #}
      <div class=\"gad-card\">
        <div class=\"gad-card-header\">
          <span class=\"gad-card-icon\">🎓</span>
          <span class=\"gad-card-title\">Certificate</span>
        </div>
        <div class=\"gad-card-body\">
          {% if doc.certificate %}
            <a href=\"{{ doc.certificate }}\" target=\"_blank\" class=\"gad-cert-link\">
              <svg width=\"14\" height=\"14\" viewBox=\"0 0 14 14\" fill=\"none\"><path d=\"M2 11L7 2l5 9H2z\" stroke=\"currentColor\" stroke-width=\"1.5\" stroke-linejoin=\"round\"/></svg>
              Download Certificate
            </a>
            {% if ws == 'Approved' %}
            <a href=\"/api/method/frappe.utils.print_format.download_pdf?doctype=Activity%20Management&name={{ doc.name }}\" target=\"_blank\" class=\"gad-cert-link\" style=\"margin-top:10px; display:inline-flex; background:#1D9E75;\">
              <svg width=\"14\" height=\"14\" viewBox=\"0 0 14 14\" fill=\"none\"><path d=\"M7 1v8M4 6l3 3 3-3M2 11h10\" stroke=\"currentColor\" stroke-width=\"1.8\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></svg>
              Download PDF Report
            </a>
            {% endif %}
          {% else %}
            <p class=\"gad-cert-none\">No certificate uploaded.</p>
          {% endif %}
        </div>
      </div>

      {# ── Workflow Timeline ── #}
      <div class=\"gad-card\">
        <div class=\"gad-card-header\">
          <span class=\"gad-card-icon\">🔄</span>
          <span class=\"gad-card-title\">Approval Timeline</span>
        </div>
        <div class=\"gad-timeline\">

          {# Step 1: Draft #}
          <div class=\"gad-tl-item\">
            <div class=\"gad-tl-left\">
              <div class=\"gad-tl-dot done\">✓</div>
              <div class=\"gad-tl-line\"></div>
            </div>
            <div class=\"gad-tl-right\">
              <div class=\"gad-tl-state\">Draft Created</div>
              <div class=\"gad-tl-desc\">Activity submitted by student</div>
            </div>
          </div>

          {# Step 2: Pending Approval #}
          <div class=\"gad-tl-item\">
            <div class=\"gad-tl-left\">
              {% if ws in ('Pending Approval', 'Approved', 'Rejected') %}
              <div class=\"gad-tl-dot {% if ws == 'Pending Approval' %}active{% else %}done{% endif %}\">
                {% if ws == 'Pending Approval' %}⏳{% else %}✓{% endif %}
              </div>
              {% else %}
              <div class=\"gad-tl-dot future\">○</div>
              {% endif %}
              <div class=\"gad-tl-line\"></div>
            </div>
            <div class=\"gad-tl-right\">
              <div class=\"gad-tl-state\">Submitted for Review</div>
              <div class=\"gad-tl-desc\">Awaiting faculty or dept. head approval</div>
            </div>
          </div>

          {# Step 3: Approved or Rejected #}
          {% if ws == 'Rejected' %}
          <div class=\"gad-tl-item\">
            <div class=\"gad-tl-left\">
              <div class=\"gad-tl-dot rejected\">✗</div>
              <div class=\"gad-tl-line\"></div>
            </div>
            <div class=\"gad-tl-right\">
              <div class=\"gad-tl-state\">Rejected</div>
              <div class=\"gad-tl-desc\">Edit and resubmit to try again</div>
            </div>
          </div>
          {% else %}
          <div class=\"gad-tl-item\">
            <div class=\"gad-tl-left\">
              <div class=\"gad-tl-dot {% if ws == 'Approved' %}done{% else %}future{% endif %}\">
                {% if ws == 'Approved' %}✓{% else %}○{% endif %}
              </div>
            </div>
            <div class=\"gad-tl-right\">
              <div class=\"gad-tl-state\">Approved &amp; Verified</div>
              <div class=\"gad-tl-desc\">Achievement officially verified</div>
            </div>
          </div>
          {% endif %}

        </div>
      </div>

      {# ── Photos Gallery ── #}
      {% if doc.photos %}
      <div class=\"gad-card full\">
        <div class=\"gad-card-header\">
          <span class=\"gad-card-icon\">📸</span>
          <span class=\"gad-card-title\">Photos ({{ doc.photos | length }})</span>
        </div>
        <div class=\"gad-card-body\">
          <div class=\"gad-gallery\">
            {% for photo in doc.photos %}
              {% if photo.photo %}
              <div>
                <div class=\"gad-gallery-item\">
                  <img src=\"{{ photo.photo }}\" alt=\"{{ photo.description or 'Activity photo' }}\" onclick=\"openLightbox('{{ photo.photo }}')\" />
                </div>
                {% if photo.description %}
                <div class=\"gad-gallery-cap\">{{ photo.description }}</div>
                {% endif %}
              </div>
              {% endif %}
            {% endfor %}
          </div>
        </div>
      </div>
      {% endif %}

    </div>{# end grid #}

    {# ── Footer actions ── #}
    <div class=\"gad-footer-actions\">
      <a href=\"/student-dashboard\" class=\"gad-action-btn\">← Back to Dashboard</a>
      {% if ws in ('Draft', 'Rejected') %}
        <a href=\"/activities/{{ doc.name }}\" class=\"gad-action-btn primary\">Edit Activity</a>
      {% endif %}
      {% if ws == 'Approved' %}
        <a href=\"/api/method/frappe.utils.print_format.download_pdf?doctype=Activity%20Management&name={{ doc.name }}\" target=\"_blank\" class=\"gad-action-btn primary\">Download PDF Report</a>
      {% endif %}
    </div>

    {% endif %}{# end doc check #}
  {% endif %}{# end doc_name check #}

  </div>
</div>

{# ── Lightbox ── #}
<div class=\"gad-lightbox\" id=\"gad-lightbox\" onclick=\"closeLightbox(event)\">
  <button class=\"gad-lightbox-close\" onclick=\"document.getElementById('gad-lightbox').classList.remove('open')\">✕</button>
  <img id=\"gad-lightbox-img\" src=\"\" alt=\"\" />
</div>

<script>
function openLightbox(src) {
  document.getElementById('gad-lightbox-img').src = src;
  document.getElementById('gad-lightbox').classList.add('open');
}
function closeLightbox(e) {
  if (e.target === document.getElementById('gad-lightbox')) {
    document.getElementById('gad-lightbox').classList.remove('open');
  }
}
document.addEventListener('keydown', function(e) {
  if (e.key === 'Escape') document.getElementById('gad-lightbox').classList.remove('open');
});
</script>
